import json
with open('/app/resources/treasury_bulletin_1991_09.json') as f:
    data = json.load(f)

# Try to find saving rate data in the JSON structure
def search_nested(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'saving' in str(k).lower():
                print(f'Found key: {new_path}')
                print(f'  Value: {str(v)[:200]}')
            search_nested(v, new_path)
    elif isinstance(obj, list) and len(obj) < 100:
        for i, item in enumerate(obj[:20]):
            search_nested(item, f'{path}[{i}]')

search_nested(data)
"
